SELECT DATE_TRUNC('MONTH', s.opened_date) AS opened_month, AVG(ss.revenue) AS avg_revenue FROM store_sales ss INNER JOIN products p ON ss.product_id = p.id INNER JOIN stores s ON ss.store_id = s.id GROUP BY DATE_TRUNC('MONTH', s.opened_date) HAVING avg_revenue > 2900 ORDER BY avg_revenue DESC, 1 LIMIT 1;
